vec3 P=aO+direction*along,side=normalize(cross(direction,P-cameraPosition));
vS=s;vY=position.y;vF=1.-clamp((u-tt)/.2,0.,1.);vU2=uTime;vLen=head-tail;
gl_Position=projectionMatrix*viewMatrix*vec4(P+side*position.y*radius,1.);}

