uniform vec3 uGold, uOrange; varying float vS, vY, vF, vU2, vLen;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      float s = vS, y = vY, t = vU2, m = s*vLen;                   /* m: metres from the tail */
      float dens = 0.;
      for (int i = 0; i < 5; i++){ float fi = float(i), ph = fi*1.7;
        float yc = (fi - 2.)*.42*(1. - s) + .16*sin(m*2.6 - t*9. + ph)*(1. - s);     /* tongues fan out behind the head */
        float L = .45 + .5*fract(fi*.618 + .3);                                              /* each tongue has its own length */
